	ticks: number[];
	labels: string[];
}

/** Cumulative-return curve in percent; a missing point carries over the previous value (0 before the first). */
export function curveView(trial: ScreenTrial | undefined | null): CurveView | null {
	const curve = trial?.curve;
	if (!curve || !curve.t || curve.t.length < 2) return null;
	const toPercent = (series: (number | null)[]) => {
		let prev = 0;
		return curve.t.map((_, i) => {
			const v = series?.[i];
			if (v != null && Number.isFinite(v)) prev = v;
			return prev * 100;
		});
	};
	const rule = toPercent(curve.rule ?? []);
	const hold = toPercent(curve.hold ?? []);
	const all = [...rule, ...hold];
	return {
		t: curve.t,
		rule,
		hold,
		ticks: niceTicks(Math.min(...all), Math.max(...all)),
		labels: curve.t.map(dateLabel),
	};
}

export interface ScreenRuleTile {
	id: string;
	group: string;
	name: string;
	label: string;
	tip: string;
}

/** The entry/fill/exit rule tiles for a (doc, feature, trial). */
export function screenRule(doc: ScreenDoc, f: ScreenFeature, trial: ScreenTrial): ScreenRuleTile[] {
	const fixed = doc.fixed_sign;
	const sign = fixed ?? trial.train_sign;
	const foldSigns = new Set((trial.folds ?? []).map((fold) => fold.train_sign));
	const signChanged = fixed == null && foldSigns.size > 1;
	const long = sign >= 0;
	const direction: ScreenRuleTile = {
		id: "direction",
		group: "entry",
		name: long ? "기준 위면 롱" : "기준 위면 숏",
		label: signChanged ? "부호 바뀜" : long ? "순방향" : "역추세",
		tip:
			fixed != null
				? `방향 부호를 ${fixed > 0 ? "+1" : fixed < 0 ? "\u22121" : "0"}로 고정한다. 기준 위면 ${long ? "롱" : "숏"}으로 읽는다.`
				: signChanged
					? "학습 연도마다 방향 부호가 바뀌었다. 해마다 부호가 달라 같은 지표라도 읽는 방향이 바뀐다."
					: `학습 때 구한 방향 부호 ${sign > 0 ? "+1" : "\u22121"}를 ${long ? "그대로" : "뒤집어"} 읽는다.`,
	};
	const indicator: ScreenRuleTile = {
		id: "indicator",
		group: "entry",
		name: featureName(f),
		label: f.tradeable === false ? "참고 지표" : "거래 가능",
		tip: featureDef(f) || f.feature,
	};
	const tiles: ScreenRuleTile[] = [direction, indicator];
	if (doc.regime === "down") {
		tiles.push({
			id: "regime",
			group: "entry",
			name: "하락장에서만",
			label: "레짐",
			tip: "종가가 200일 평균 아래인 날만 점수를 매기고 매매한다.",
		});
	}
	tiles.push(
		{
			id: "fill",
			group: "fill",
			name: `편도 ${Math.round(doc.cost_per_side * 1e4)}bp`,
			label: "비용",
			tip: "한쪽으로 사고파는 데 드는 비용을 뺀 뒤의 수익이다.",
		},
		{
			id: "hold",
			group: "exit",
			name: `${trial.h}${doc.unit} 보유`,
			label: "보유",
			tip: `진입 후 ${trial.h}${doc.unit} 동안 보유하고 청산한다.`,
		},
	);
	return tiles;
}

